<?php $byModule=[];foreach($permissions as $permission)$byModule[$permission['module']][]=$permission;?><div class="page-heading admin-heading"><div><a class="back-link" href="<?= url('admin/users') ?>">← Users</a><span class="eyebrow">Least-privilege access</span><h1>Roles & permissions</h1><p>Configure exactly what each operational role can view or change.</p></div></div><div class="report-notice"><span>⌾</span><p>Super Admin always has full system authority. Applicant access is controlled by dedicated student routes. Those two system roles are intentionally protected from matrix editing.</p></div><div class="role-matrix-list"><?php foreach($roles as $role): $protected=in_array($role['slug'],['super-admin','applicant'],true);?><section class="card role-editor" id="role-<?= e($role['id']) ?>"><header><div><span class="role-symbol"><?= e(strtoupper(substr($role['name'],0,1))) ?></span><span><b><?= e($role['name']) ?></b><small><?= e($role['description']) ?></small></span></div><div><span class="role-user-count"><?= e($role['user_count']) ?> user(s)</span><?php if($protected):?><span class="status-pill status-active">Protected</span><?php endif?></div></header><form method="post" action="<?= url('admin/roles/'.$role['id']) ?>"><?= csrf_field() ?><div class="permission-modules"><?php foreach($byModule as $module=>$modulePermissions):?><fieldset><legend><?= e(ucwords(str_replace('_',' ',$module))) ?></legend><?php foreach($modulePermissions as $permission):?><label><input type="checkbox" name="permissions[]" value="<?= e($permission['id']) ?>" <?= checked($role['slug']==='super-admin'||in_array((int)$permission['id'],$assigned[(int)$role['id']]??[],true)) ?> <?= $protected?'disabled':'' ?>><span><b><?= e($permission['name']) ?></b><small><?= e($permission['slug']) ?></small></span></label><?php endforeach?></fieldset><?php endforeach?></div><?php if(!$protected):?><div class="role-save"><span>Changes apply to all users assigned this role.</span><button class="button button-primary button-sm">Save <?= e($role['name']) ?> permissions</button></div><?php endif?></form></section><?php endforeach?></div>
